/**
 * pyint.mjs — Python `int(str)` semantics, faithfully reproduced in JavaScript.
 *
 * Exports:
 *   - PyValueError        : ValueError-equivalent carrying `pyType === 'ValueError'`
 *   - pyStrip(s)          : Python `str.strip()` (no-arg form, Unicode whitespace set)
 *   - isPyDecimalDigit(cp): true iff code point `cp` is Unicode category Nd
 *   - pyDigitValue(cp)    : numeric value 0..9 of an Nd code point
 *   - pyInt(s)            : full `int(str)` parse, returning an exact BigInt
 *
 * Arbitrary precision is preserved by accumulating into a BigInt
 * (`v = v * 10n + BigInt(d)`), matching CPython's unbounded ints.
 */

import { pyRepr } from './pyrepr.mjs';

/**
 * Equivalent of Python's built-in `ValueError`.
 * `pyType` lets higher layers format tracebacks without instanceof plumbing.
 */
export class PyValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'PyValueError';
    /** @type {string} */
    this.pyType = 'ValueError';
  }
}

/**
 * The exact set of code points for which CPython's `str.isspace()` is true and
 * which therefore get removed by the no-argument `str.strip()`.
 *
 * Note the deliberate omissions: U+200B ZERO WIDTH SPACE and U+FEFF are *not*
 * whitespace in Python, so `int('3​')` must raise.
 */
const PY_WHITESPACE = new Set([
  0x09, // \t  CHARACTER TABULATION
  0x0a, // \n  LINE FEED
  0x0b, // \v  LINE TABULATION
  0x0c, // \f  FORM FEED
  0x0d, // \r  CARRIAGE RETURN
  0x1c, //     FILE SEPARATOR
  0x1d, //     GROUP SEPARATOR
  0x1e, //     RECORD SEPARATOR
  0x1f, //     UNIT SEPARATOR
  0x20, //     SPACE
  0x85, //     NEXT LINE
  0xa0, //     NO-BREAK SPACE
  0x1680, //   OGHAM SPACE MARK
  0x2000, //   EN QUAD .. HAIR SPACE (0x2000-0x200A)
  0x2001,
  0x2002,
  0x2003,
  0x2004,
  0x2005,
  0x2006,
  0x2007,
  0x2008,
  0x2009,
  0x200a,
  0x2028, //   LINE SEPARATOR
  0x2029, //   PARAGRAPH SEPARATOR
  0x202f, //   NARROW NO-BREAK SPACE
  0x205f, //   MEDIUM MATHEMATICAL SPACE
  0x3000, //   IDEOGRAPHIC SPACE
]);

/**
 * Python `str.strip()` — remove leading and trailing Unicode whitespace.
 * Operates on code points so astral characters are never split.
 *
 * @param {string} s
 * @returns {string}
 */
export function pyStrip(s) {
  const cps = [...s];
  let start = 0;
  let end = cps.length;
  while (start < end && PY_WHITESPACE.has(cps[start].codePointAt(0))) start += 1;
  while (end > start && PY_WHITESPACE.has(cps[end - 1].codePointAt(0))) end -= 1;
  return cps.slice(start, end).join('');
}

/** Memo for Nd membership tests, keyed by code point. */
const ndCache = new Map();

/** Memo for Nd digit values, keyed by code point. */
const digitValueCache = new Map();

const ND_RE = /\p{Nd}/u;

/**
 * Is `cp` a Unicode decimal digit (general category Nd)?
 * This covers ASCII 0-9 plus Arabic-Indic, Devanagari, fullwidth, etc.
 * Superscripts like '²' are category No and are correctly excluded.
 *
 * @param {number} cp code point
 * @returns {boolean}
 */
export function isPyDecimalDigit(cp) {
  const cached = ndCache.get(cp);
  if (cached !== undefined) return cached;
  // Guard against invalid code points reaching String.fromCodePoint.
  let result = false;
  if (Number.isInteger(cp) && cp >= 0 && cp <= 0x10ffff) {
    result = ND_RE.test(String.fromCodePoint(cp));
  }
  ndCache.set(cp, result);
  return result;
}

/**
 * Numeric value (0..9) of an Nd code point.
 *
 * Nd digits always come in contiguous runs of ten starting at that script's
 * ZERO, so we locate the block zero by walking backwards at most 9 steps while
 * the preceding code point is still Nd; the value is then the offset.
 *
 * @param {number} cp code point known to satisfy isPyDecimalDigit
 * @returns {number} 0-9, or -1 if `cp` is not an Nd digit
 */
export function pyDigitValue(cp) {
  const cached = digitValueCache.get(cp);
  if (cached !== undefined) return cached;

  if (!isPyDecimalDigit(cp)) {
    digitValueCache.set(cp, -1);
    return -1;
  }

  let zero = cp;
  for (let step = 0; step < 9; step += 1) {
    if (!isPyDecimalDigit(zero - 1)) break;
    zero -= 1;
  }

  const value = cp - zero;
  digitValueCache.set(cp, value);
  return value;
}

/**
 * Python `int(s)` with base 10.
 *
 * Grammar accepted after `str.strip()`:
 *     [ '+' | '-' ] digit ( '_'? digit )*
 * where `digit` is any Unicode Nd code point. Underscores are permitted only as
 * single separators *between* digits, so '_1', '1_' and '1__0' all raise.
 * Only ASCII '+'/'-' are signs — U+2212 MINUS SIGN is rejected.
 *
 * @param {string} s
 * @returns {bigint} exact value; '-0' normalizes to 0n
 * @throws {PyValueError} on any malformed literal
 */
export function pyInt(s) {
  const original = s;

  const fail = () => {
    throw new PyValueError(
      `invalid literal for int() with base 10: ${pyRepr(original)}`,
    );
  };

  if (typeof s !== 'string') fail();

  // Iterate by code point, not UTF-16 unit, so astral digits work.
  const cps = [...pyStrip(s)];
  let i = 0;

  // Optional ASCII sign.
  let negative = false;
  if (i < cps.length && (cps[i] === '+' || cps[i] === '-')) {
    negative = cps[i] === '-';
    i += 1;
  }

  // At least one digit is required immediately after the sign.
  if (i >= cps.length) fail();

  let value = 0n;
  let sawDigit = false;
  let prevWasUnderscore = false;

  for (; i < cps.length; i += 1) {
    const ch = cps[i];

    if (ch === '_') {
      // An underscore must be preceded by a digit and followed by a digit.
      if (!sawDigit || prevWasUnderscore) fail();
      prevWasUnderscore = true;
      continue;
    }

    const d = pyDigitValue(ch.codePointAt(0));
    if (d < 0) fail();

    value = value * 10n + BigInt(d);
    sawDigit = true;
    prevWasUnderscore = false;
  }

  // A trailing underscore ('1_') leaves the flag set; a digitless body fails too.
  if (!sawDigit || prevWasUnderscore) fail();

  // BigInt has no negative zero, but normalize explicitly for clarity.
  if (value === 0n) return 0n;
  return negative ? -value : value;
}

input.command:
set -e
T=$(mktemp -d)
cp /output/lib/pyint.mjs "$T/pyint.mjs"
cat > "$T/pyrepr.mjs" <<'EOF'
export function pyRepr(v){ return JSON.stringify(v); }
EOF
cat > "$T/t.mjs" <<'EOF'
import {pyInt, pyStrip, pyDigitValue, isPyDecimalDigit, PyValueError} from './pyint.mjs';
const ok=[['1',1n],['+5',5n],['-0',0n],['007',7n],['1_000',1000n],['  -5  ',-5n],
 ['٣',3n],['١٢',12n],['१२',12n],['１２３',123n],
 ['12345678901234567890',12345678901234567890n],
 ['999999999999999999999999999999',999999999999999999999999999999n],
 ['-98765432109876543210',-98765432109876543210n],
 [' 1　',1n],['\u{1D7CF}\u{1D7D0}',12n]];
for(const [s,e] of ok){const g=pyInt(s); if(g!==e) console.log('FAIL',JSON.stringify(s),g,e); }
const bad=['','   ','_1','1_','1__0','0x10','1.0','-3.5','- 3','²','3​','−3','+','-','1 2','٣٤_','abc'];
for(const s of bad){ let t=false; try{pyInt(s);}catch(e){ t = e instanceof PyValueError && e.pyType==='ValueError';} if(!t) console.log('SHOULD RAISE',JSON.stringify(s), (()=>{try{return pyInt(s)}catch(e){return 'err:'+e.constructor.name}})()); }
console.log('strip 200b kept:', JSON.stringify(pyStrip('3​')));
console.log('digits:', pyDigitValue(0x0669), isPyDecimalDigit(0x00b2), pyDigitValue('９'.codePointAt(0)));
try{pyInt('0x10')}catch(e){console.log('msg:',e.message)}
console.log('exports OK');
EOF
node "$T/t.mjs"
rm -rf "$T"

node --input-type=module -e "
import {pyInt} from '/output/lib/pyint.mjs';
for (const s of ['0x10','3​','-3.5','1__0','\$\$bad']) { try { pyInt(s); console.log('no raise', s); } catch(e) { console.log(e.pyType+':', e.message); } }
console.log(pyInt('  -5  '), pyInt('+5'), pyInt('-0'), pyInt('1_000'), pyInt('٣'), pyInt('999999999999999999999999999999'));
"
